1	import { VEA_ROUTES } from "./config";
2	import type { VeaClaim, VeaEpochRow, VeaMessageRow, VeaRoute, VeaSnapshot } from "./types";
3	import { deriveStatus } from "./status";
4	
5	const ENVIO_URL = import.meta.env.VITE_ENVIO_URL ?? "http://localhost:8080/v1/graphql";
6	
7	const FETCH_TIMEOUT_MS = 5_000;
8	
9	// Envio's HyperIndex GraphQL API caps unpaginated/unbatched queries at this
10	// default row limit — used both as the page size for GetMessages and the
11	// batch size for GetRelayed's `_in` filter.
12	const GQL_PAGE_SIZE = 1000;
13	
14	/** Thrown when a request needed to assemble a full result fails partway
15	 *  through, so callers can tell "the indexer is unreachable" apart from
16	 *  "the data is genuinely empty" instead of silently returning partial data. */
17	export class VeaIndexerError extends Error {
18	  constructor(message = "Could not reach the Vea indexer.") {
19	    super(message);
20	    this.name = "VeaIndexerError";
21	  }
22	}
