24	async function gql<T>(url: string, query: string, variables: Record<string, unknown>): Promise<T | null> {
25	  const controller = new AbortController();
26	  const timer = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);
27	  try {
28	    const res = await fetch(url, {
29	      method: "POST",
30	      headers: { "Content-Type": "application/json" },
31	      body: JSON.stringify({ query, variables }),
32	      signal: controller.signal,
33	    });
34	    if (!res.ok) return null;
35	    const json = await res.json();
36	    if (json.errors) {
37	      console.error("Vea GraphQL errors:", json.errors);
38	      return null;
39	    }
40	    return json.data as T;
41	  } catch (err) {
42	    console.error("Vea GraphQL request failed:", err);
43	    return null;
44	  } finally {
45	    clearTimeout(timer);
46	  }
47	}
