49	const SNAPSHOT_FIELDS = `
50	  id epoch caller txHash timestamp stateRoot numberMessages saved resolving
51	  fallback { executor timestamp txHash ticketId }
52	`;
53	
54	const CLAIM_FIELDS = `
55	  id epoch stateRoot bridger timestamp txHash challenged verified
56	  challenge { txHash timestamp challenger }
57	  verification { startTimestamp startCaller startTxHash verifiedTimestamp verifiedCaller verifiedTxHash }
58	`;
