60	interface RawFallback {
61	  executor: string;
62	  timestamp: string | null;
63	  txHash: string;
64	  ticketId: string;
65	}
66	
67	interface RawSnapshot {
68	  id: string;
69	  epoch: string | null;
70	  caller: string | null;
71	  txHash: string | null;
72	  timestamp: string | null;
73	  stateRoot: string | null;
74	  numberMessages: string;
75	  saved: boolean;
76	  resolving: boolean;
77	  fallback: RawFallback[];
78	}
79	
80	interface RawChallenge {
81	  txHash: string;
82	  timestamp: string;
83	  challenger: string;
84	}
85	
86	interface RawVerification {
87	  startTimestamp: string | null;
88	  startCaller: string | null;
89	  startTxHash: string | null;
90	  verifiedTimestamp: string | null;
91	  verifiedCaller: string | null;
92	  verifiedTxHash: string | null;
93	}
94	
95	interface RawClaim {
96	  id: string;
97	  epoch: string;
98	  stateRoot: string;
99	  bridger: string;
100	  timestamp: string;
101	  txHash: string;
102	  challenged: boolean;
103	  verified: boolean;
104	  challenge: RawChallenge[];
105	  verification: RawVerification[];
106	}
