108	function toSnapshot(s: RawSnapshot): VeaSnapshot {
109	  return {
110	    id: s.id,
111	    epoch: s.epoch !== null ? Number(s.epoch) : undefined,
112	    caller: s.caller ?? undefined,
113	    txHash: s.txHash ?? undefined,
114	    timestamp: s.timestamp !== null ? Number(s.timestamp) : undefined,
115	    stateRoot: s.stateRoot ?? undefined,
116	    numberMessages: Number(s.numberMessages),
117	    saved: s.saved,
118	    resolving: s.resolving,
119	    fallback: s.fallback.map((f) => ({
120	      executor: f.executor,
121	      timestamp: f.timestamp !== null ? Number(f.timestamp) : undefined,
122	      txHash: f.txHash,
123	      ticketId: f.ticketId,
124	    })),
125	  };
126	}
127	
128	function toClaim(c: RawClaim): VeaClaim {
129	  return {
130	    id: c.id,
131	    epoch: Number(c.epoch),
132	    stateRoot: c.stateRoot,
133	    bridger: c.bridger,
134	    timestamp: Number(c.timestamp),
135	    txHash: c.txHash,
136	    challenged: c.challenged,
137	    verified: c.verified,
138	    challenge: c.challenge.map((ch) => ({
139	      txHash: ch.txHash,
140	      timestamp: Number(ch.timestamp),
141	      challenger: ch.challenger,
142	    })),
143	    verification: c.verification.map((v) => ({
144	      startTimestamp: v.startTimestamp !== null ? Number(v.startTimestamp) : undefined,
145	      startCaller: v.startCaller ?? undefined,
146	      startTxHash: v.startTxHash ?? undefined,
147	      verifiedTimestamp: v.verifiedTimestamp !== null ? Number(v.verifiedTimestamp) : undefined,
148	      verifiedCaller: v.verifiedCaller ?? undefined,
149	      verifiedTxHash: v.verifiedTxHash ?? undefined,
150	    })),
151	  };
152	}
