154	function toRow(route: VeaRoute, epoch: number, snapshot: VeaSnapshot | null, claim: VeaClaim | null): VeaEpochRow {
155	  return { route, epoch, snapshot, claim, status: deriveStatus(snapshot, claim) };
156	}
