158	/** Per-route cap on fetched snapshots — mirrors Home.tsx's fetch-a-bounded-window,
159	 *  then-paginate-client-side pattern rather than server-side offset pagination
160	 *  (Envio's HyperIndex GraphQL API has no `_aggregate` support at all, confirmed
161	 *  via introspection against a live indexer, so there's no total count to page
162	 *  against server-side either way). Generous relative to real snapshot cadence
163	 *  (roughly one every 1-2 days per route in observed data). */
164	const SNAPSHOT_WINDOW = 200;
165	
166	async function fetchRouteSnapshots(route: VeaRoute): Promise<VeaSnapshot[] | null> {
167	  const query = `
168	    query GetSnapshots($inbox: String!, $limit: Int!) {
169	      Snapshot(
170	        where: { inbox_id: { _eq: $inbox }, saved: { _eq: true } }
171	        order_by: { timestamp: desc }
172	        limit: $limit
173	      ) { ${SNAPSHOT_FIELDS} }
174	    }
175	  `;
176	  const data = await gql<{ Snapshot: RawSnapshot[] }>(ENVIO_URL, query, {
177	    inbox: route.inboxAddress,
178	    limit: SNAPSHOT_WINDOW,
179	  });
180	  return data ? data.Snapshot.map(toSnapshot) : null;
181	}
