183	/**
184	 * Fetches the recent window of epochs across one or more routes (one inbox
185	 * query per route, in parallel) and merges them into a single list sorted
186	 * newest-first — used for both a single selected route and the "All Chains"
187	 * merged view. Claims are then batch-fetched one query per *distinct outbox*
188	 * among the matched routes, not one query overall: epoch numbers are only
189	 * unique within a single outbox, so merging routes without this would let a
190	 * claim from one bridge get matched to an unrelated epoch on another.
191	 */
192	export async function fetchEpochs(routes: VeaRoute[]): Promise<VeaEpochRow[] | null> {
193	  if (routes.length === 0) return [];
194	
195	  const perRoute = await Promise.all(
196	    routes.map(async (route) => ({ route, snapshots: await fetchRouteSnapshots(route) }))
197	  );
198	  const succeeded = perRoute.filter((r): r is { route: VeaRoute; snapshots: VeaSnapshot[] } => r.snapshots !== null);
199	  if (succeeded.length === 0) return null;
200	
201	  const entries = succeeded.flatMap(({ route, snapshots }) =>
202	    snapshots
203	      .filter((s): s is VeaSnapshot & { epoch: number } => s.epoch !== undefined)
204	      .map((snapshot) => ({ route, epoch: snapshot.epoch, snapshot }))
205	  );
206	
207	  const epochsByOutbox = new Map<string, Set<number>>();
208	  for (const entry of entries) {
209	    const set = epochsByOutbox.get(entry.route.outboxAddress);
210	    if (set) set.add(entry.epoch);
211	    else epochsByOutbox.set(entry.route.outboxAddress, new Set([entry.epoch]));
212	  }
213	
214	  const claimQuery = `
215	    query GetClaims($outbox: String!, $epochs: [numeric!]!) {
216	      Claim(where: { outbox_id: { _eq: $outbox }, epoch: { _in: $epochs } }) { ${CLAIM_FIELDS} }
217	    }
218	  `;
219	  const outboxEntries = [...epochsByOutbox.entries()];
220	  const claimResults = await Promise.all(
221	    outboxEntries.map(([outboxAddress, epochs]) =>
222	      gql<{ Claim: RawClaim[] }>(ENVIO_URL, claimQuery, { outbox: outboxAddress, epochs: [...epochs].map(String) })
223	    )
224	  );
225	  const claimByKey = new Map<string, VeaClaim>();
226	  const failedOutboxes = new Set<string>();
227	  outboxEntries.forEach(([outboxAddress], i) => {
228	    const result = claimResults[i];
229	    if (result === null) {
230	      failedOutboxes.add(outboxAddress);
231	      return;
232	    }
233	    for (const rawClaim of result.Claim) {
234	      const claim = toClaim(rawClaim);
235	      claimByKey.set(`${outboxAddress}_${claim.epoch}`, claim);
236	    }
237	  });
238	
239	  return entries
240	    .map(({ route, epoch, snapshot }) => {
241	      const claim = claimByKey.get(`${route.outboxAddress}_${epoch}`) ?? null;
242	      const row = toRow(route, epoch, snapshot, claim);
243	      // A failed claim query is indistinguishable from "no claims yet" at the
244	      // data level, but deriveStatus would otherwise mislabel it "Saved" —
245	      // surface it as Unknown instead of implying the epoch is unclaimed.
246	      if (claim === null && failedOutboxes.has(route.outboxAddress)) {
247	        return { ...row, status: "Unknown" as const };
248	      }
249	      return row;
250	    })
251	    .sort((a, b) => (b.snapshot?.timestamp ?? 0) - (a.snapshot?.timestamp ?? 0));
252	}
