254	export interface EpochDetail {
255	  row: VeaEpochRow;
256	  messages: VeaMessageRow[];
257	}
258	
259	/**
260	 * Fetches a single epoch's Snapshot + Claim, plus every Message in that
261	 * snapshot, each annotated Executed/Pending by matching the inbox message's
262	 * nonce (parsed from its id, `${inboxAddress}-${nonce}`) against an outbox
263	 * Message with id `${outboxAddress}-${nonce}` — msgId and nonce are the
264	 * same sequential index, per VeaOutbox's own docstring on `_msgId`.
265	 */
266	export async function fetchEpochDetail(route: VeaRoute, epoch: number): Promise<EpochDetail | null> {
267	  const snapshotQuery = `
268	    query GetSnapshot($inbox: String!, $epoch: numeric!) {
269	      Snapshot(where: { inbox_id: { _eq: $inbox }, epoch: { _eq: $epoch } }, limit: 1) { ${SNAPSHOT_FIELDS} }
270	    }
271	  `;
272	  const snapshotData = await gql<{ Snapshot: RawSnapshot[] }>(ENVIO_URL, snapshotQuery, {
273	    inbox: route.inboxAddress,
274	    epoch: String(epoch),
275	  });
276	  if (!snapshotData || snapshotData.Snapshot.length === 0) return null;
277	  const snapshot = toSnapshot(snapshotData.Snapshot[0]);
278	
279	  const claimQuery = `
280	    query GetClaim($outbox: String!, $epoch: numeric!) {
281	      Claim(where: { outbox_id: { _eq: $outbox }, epoch: { _eq: $epoch } }, limit: 1) { ${CLAIM_FIELDS} }
282	    }
283	  `;
284	  const claimData = await gql<{ Claim: RawClaim[] }>(ENVIO_URL, claimQuery, {
285	    outbox: route.outboxAddress,
286	    epoch: String(epoch),
287	  });
288	  const claim = claimData?.Claim[0] ? toClaim(claimData.Claim[0]) : null;
289	
290	  const messagesQuery = `
291	    query GetMessages($snapshot: String!, $limit: Int!, $offset: Int!) {
292	      Message(
293	        where: { snapshot_id: { _eq: $snapshot } }
294	        order_by: { timestamp: asc }
295	        limit: $limit
296	        offset: $offset
297	      ) {
298	        id txHash timestamp from to
299	      }
300	    }
301	  `;
302	  type RawMessage = { id: string; txHash: string; timestamp: string; from: string; to: string };
303	  const inboxMessages: RawMessage[] = [];
304	  for (let offset = 0; ; offset += GQL_PAGE_SIZE) {
305	    const page = await gql<{ Message: RawMessage[] }>(ENVIO_URL, messagesQuery, {
306	      snapshot: snapshot.id,
307	      limit: GQL_PAGE_SIZE,
308	      offset,
309	    });
310	    if (page === null) throw new VeaIndexerError();
311	    inboxMessages.push(...page.Message);
312	    if (page.Message.length < GQL_PAGE_SIZE) break;
313	  }
314	
315	  const outboxIds = inboxMessages.map((m) => `${route.outboxAddress}-${m.id.split("-")[1]}`);
316	  const relayedById = new Map<string, { id: string; txHash: string; relayer: string }>();
317	  const relayedQuery = `
318	    query GetRelayed($ids: [String!]!) { MessageExecution(where: { id: { _in: $ids } }) { id txHash relayer } }
319	  `;
320	  const relayedBatches = await Promise.all(
321	    Array.from({ length: Math.ceil(outboxIds.length / GQL_PAGE_SIZE) }, (_, i) =>
322	      gql<{ MessageExecution: { id: string; txHash: string; relayer: string }[] }>(ENVIO_URL, relayedQuery, {
323	        ids: outboxIds.slice(i * GQL_PAGE_SIZE, (i + 1) * GQL_PAGE_SIZE),
324	      })
325	    )
326	  );
327	  for (const batch of relayedBatches) {
328	    if (batch === null) throw new VeaIndexerError();
329	    for (const m of batch.MessageExecution) {
330	      relayedById.set(m.id, m);
331	    }
332	  }
333	
334	  const messages: VeaMessageRow[] = inboxMessages.map((m) => {
335	    const nonce = m.id.split("-")[1];
336	    const relayed = relayedById.get(`${route.outboxAddress}-${nonce}`);
337	    return {
338	      id: m.id,
339	      nonce: Number(nonce),
340	      txHash: m.txHash,
341	      timestamp: Number(m.timestamp),
342	      from: m.from,
343	      to: m.to,
344	      executed: !!relayed,
345	      relayedTxHash: relayed?.txHash,
346	      relayer: relayed?.relayer,
347	    };
348	  });
349	
350	  return { row: toRow(route, epoch, snapshot, claim), messages };
351	}
