353	export interface EpochLocation {
354	  route: VeaRoute;
355	  epoch: number;
356	}
357	
358	/**
359	 * Searches every known route's inbox Snapshot and outbox Claim for this exact
360	 * transaction hash (the SnapshotSaved or Claimed tx — the two "creation"
361	 * events, mirroring the Hashi search bar's dispatch-tx-only scope, not every
362	 * downstream event). Case-insensitive: tx hashes are stored lowercase, as
363	 * emitted by the indexer, same convention as `lib/envioClient.ts`.
364	 */
365	export async function findEpochByTxHash(txHash: string): Promise<EpochLocation | null> {
366	  const normalized = txHash.toLowerCase();
367	
368	  const snapshotMatches = VEA_ROUTES.map(async (route) => {
369	    const query = `
370	      query FindSnapshotByTx($inbox: String!, $tx: String!) {
371	        Snapshot(where: { inbox_id: { _eq: $inbox }, txHash: { _eq: $tx } }, limit: 1) { epoch }
372	      }
373	    `;
374	    const data = await gql<{ Snapshot: { epoch: string | null }[] }>(ENVIO_URL, query, {
375	      inbox: route.inboxAddress,
376	      tx: normalized,
377	    });
378	    const epoch = data?.Snapshot[0]?.epoch;
379	    return epoch !== undefined && epoch !== null ? { route, epoch: Number(epoch) } : null;
380	  });
381	
382	  const claimMatches = VEA_ROUTES.map(async (route) => {
383	    const query = `
384	      query FindClaimByTx($outbox: String!, $tx: String!) {
385	        Claim(where: { outbox_id: { _eq: $outbox }, txHash: { _eq: $tx } }, limit: 1) { epoch }
386	      }
387	    `;
388	    const data = await gql<{ Claim: { epoch: string | null }[] }>(ENVIO_URL, query, {
389	      outbox: route.outboxAddress,
390	      tx: normalized,
391	    });
392	    const epoch = data?.Claim[0]?.epoch;
393	    return epoch !== undefined && epoch !== null ? { route, epoch: Number(epoch) } : null;
394	  });
395	
396	  const results = await Promise.all([...snapshotMatches, ...claimMatches]);
397	  return results.find((r): r is EpochLocation => r !== null) ?? null;
398	}
