400	/**
401	 * Searches every known route's inbox for a saved Snapshot at this epoch
402	 * number. Epoch numbers are only unique per-outbox (see `fetchEpochs`), so a
403	 * bare number can legitimately match more than one route — when it does,
404	 * this returns whichever match has the most recent snapshot timestamp, since
405	 * that's the one a user is most likely looking for.
406	 */
407	export async function findEpochByNumber(epoch: number): Promise<EpochLocation | null> {
408	  const query = `
409	    query FindSnapshotByEpoch($inbox: String!, $epoch: numeric!) {
410	      Snapshot(where: { inbox_id: { _eq: $inbox }, epoch: { _eq: $epoch }, saved: { _eq: true } }, limit: 1) {
411	        epoch
412	        timestamp
413	      }
414	    }
415	  `;
416	  const results = await Promise.all(
417	    VEA_ROUTES.map(async (route) => {
418	      const data = await gql<{ Snapshot: { epoch: string; timestamp: string | null }[] }>(ENVIO_URL, query, {
419	        inbox: route.inboxAddress,
420	        epoch: String(epoch),
421	      });
422	      const match = data?.Snapshot[0];
423	      return match ? { route, epoch: Number(match.epoch), timestamp: Number(match.timestamp ?? 0) } : null;
424	    })
425	  );
426	
427	  const matches = results.filter((r): r is EpochLocation & { timestamp: number } => r !== null);
428	  if (matches.length === 0) return null;
429	  return matches.reduce((latest, current) => (current.timestamp > latest.timestamp ? current : latest));
430	}
