1	import { useEffect, useState } from "react";
2	import { fetchEpochDetail, VeaIndexerError } from "@/lib/vea/client";
3	import type { VeaEpochRow, VeaMessageRow, VeaRoute } from "@/lib/vea/types";
4	
5	export function useVeaEpoch(route: VeaRoute, epoch: number) {
6	  const [row, setRow] = useState<VeaEpochRow | null>(null);
7	  const [messages, setMessages] = useState<VeaMessageRow[]>([]);
8	  const [isLoading, setIsLoading] = useState(true);
9	  const [error, setError] = useState<string | null>(null);
10	
11	  useEffect(() => {
12	    let cancelled = false;
13	    setIsLoading(true);
14	    setError(null);
15	
16	    fetchEpochDetail(route, epoch)
17	      .then((result) => {
18	        if (cancelled) return;
19	        if (result === null) {
20	          setError("Epoch not found.");
21	          setRow(null);
22	          setMessages([]);
23	        } else {
24	          setRow(result.row);
25	          setMessages(result.messages);
26	        }
27	        setIsLoading(false);
28	      })
29	      .catch((err) => {
30	        if (cancelled) return;
31	        setError(err instanceof VeaIndexerError ? err.message : "Epoch not found.");
32	        setRow(null);
33	        setMessages([]);
34	        setIsLoading(false);
35	      });
36	
37	    return () => {
38	      cancelled = true;
39	    };
40	  }, [route, epoch]);
41	
42	  return { row, messages, isLoading, error };
43	}
